cat >> tests/repositories.test.js <<'EOF'

test('PaymentRepository.findByOrders returns payments for any of the given orders', async () => {
  const repo = new PaymentRepository();
  const payments = await repo.findByOrders([10, 11, 12]);
  assert.deepEqual(payments.map((p) => p.id), [100, 101]);
  assert.deepEqual(await repo.findByOrders([]), []);
});
EOF
sed -i "s#^import { findPaymentsForOrder, uncapturedTotalCents } from#import { findPaymentsForOrder, uncapturedTotalCents, listPaymentsForUser } from#" tests/payment-service.test.js
cat >> tests/payment-service.test.js <<'EOF'

test('listPaymentsForUser returns payments across the user orders', async () => {
  const rows = await call(listPaymentsForUser, 1);
  assert.deepEqual(rows.map((p) => p.id), [100]);
  assert.deepEqual((await call(listPaymentsForUser, 2)).map((p) => p.id), [101]);
});

test('listPaymentsForUser returns an empty list for an unknown user', async () => {
  assert.deepEqual(await call(listPaymentsForUser, 999), []);
});
EOF
cat > tests/routes.test.js <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { routes, listEndpoints } from '../src/api/routes.js';

const handle = (path, params) => {
  const route = routes.find((r) => r.method === 'GET' && r.path === path);
  return new Promise((resolve, reject) =>
    route.handler({ params }, (err, data) => (err ? reject(err) : resolve(data))));
};

test('GET /users/:id/payments is registered', () => {
  assert.ok(listEndpoints().includes('GET /users/:id/payments'));
});

test('GET /users/:id/payments returns the user payments from a string id param', async () => {
  const payments = await handle('/users/:id/payments', { id: '2' });
  assert.deepEqual(payments.map((p) => p.id), [101]);
  assert.equal(payments[0].amount_cents, 9900);
});
EOF
